def parse_poly(poly):
    import re
    terms = re.split(r'([+-])', poly)
    parsed = []
    for term in terms:
        if term.strip():
            if term[0] in '+-':
                sign = term[0]
                coeff = 1 if sign == '+' else -1
                monomial = term[1:]
            else:
                sign = '+'
                coeff = 1
                monomial = term
            if monomial:
                parsed.append((coeff, monomial))
    return parsed
